// src/builder/linebreak.ts
var SPACES = "  ";
var BACKSLASH = "\\";
var HTML = "<br/>";
function linebreak(type) {
  return {
    toString() {
      switch (type) {
        case "spaces": {
          return SPACES;
        }
        case "backslash": {
          return BACKSLASH;
        }
        case "html": {
          return HTML;
        }
      }
    }
  };
}
export {
  linebreak
};
